package com.productionhouse.crm.audio.singer.service;
import com.productionhouse.crm.audio.singer.entity.SingerProfile;import com.productionhouse.crm.audio.singer.repository.SingerProfileRepository;import org.junit.jupiter.api.Test;import org.springframework.data.domain.Sort;import java.util.List;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class SingerProfileServiceTest{@Test void filtersSingerNameLanguageAndActiveState(){var repo=mock(SingerProfileRepository.class);var singer=new SingerProfile();singer.setName("Asha");singer.setLanguages("Hindi, English");singer.setStatus("ACTIVE");singer.setActive(true);var other=new SingerProfile();other.setName("Ravi");other.setLanguages("Tamil");other.setStatus("INACTIVE");other.setActive(false);when(repo.findAll(any(Sort.class))).thenReturn(List.of(singer,other));var page=new SingerProfileService(repo).list("ash","English","ACTIVE",true,0,20,"name","asc");assertEquals(1,page.getTotalElements());assertEquals("Asha",page.getContent().get(0).name());}}

